#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos;
    int cantidad_entrada{0};

    std::cin >> cantidad_entrada;

    for (int entrada{0}; entrada < cantidad_entrada; ++entrada) {
        int dato{0};
        std::cin >> dato;

        datos.push_back(dato);
    }

    for (auto& valor : datos) {
        if (valor < 4) {
            valor += 3;
        }
    }

    for (const auto& valor : datos) {
        std::cout << valor << ";";
    }

    return 0;
}

